fields.InputDefinition:
{
  "goal": "Open the 'Events' entity grid — type 'Events' in the LEFT sidebar 'Search entities...' box and click the exact 'Events' node (or, if the search is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Events). Click a row, then click 'Open Full Record'. In the record toolbar (the row of icons at the TOP-LEFT, just above the Details card), click the Tags control — the TAGS icon (tooltip 'View tags'). Verify a tags panel/area opens for the record — showing existing tags, a clear empty-tags state, or an add-tag input — with no error. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The 'View tags' (tags icon) control in the record toolbar was clicked",
    "A tags panel/area opened for the record (existing tags, empty state, or add-tag input)",
    "No error messages or crash pages"
  ]
}
